using System;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.IO;
using System.Linq;
using MessagePack.SourceGenerator;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Xunit;

public class A5_F1_ReferencedClosedGenericStructTests
{
    private static List<MetadataReference> GetBaseReferences()
    {
        var paths = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        if (AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES") is string tpa)
        {
            foreach (string p in tpa.Split(Path.PathSeparator))
            {
                if (!string.IsNullOrEmpty(p) && p.EndsWith(".dll", StringComparison.OrdinalIgnoreCase))
                {
                    paths[Path.GetFileName(p)] = p;
                }
            }
        }

        foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
        {
            if (!asm.IsDynamic && !string.IsNullOrEmpty(asm.Location))
            {
                string name = Path.GetFileName(asm.Location);
                if (!paths.ContainsKey(name))
                {
                    paths[name] = asm.Location;
                }
            }
        }

        foreach (string loc in new[] { typeof(MessagePack.MessagePackObjectAttribute).Assembly.Location, typeof(MessagePack.MessagePackSerializer).Assembly.Location })
        {
            if (!string.IsNullOrEmpty(loc))
            {
                paths[Path.GetFileName(loc)] = loc;
            }
        }

        return paths.Values.Select(p => (MetadataReference)MetadataReference.CreateFromFile(p)).ToList();
    }

    private static void RunScenario(string defineSource, string usageSource)
    {
        var parseOptions = new CSharpParseOptions(LanguageVersion.CSharp10);
        var baseRefs = GetBaseReferences();

        var defining = CSharpCompilation.Create(
            "DefiningProject",
            new[] { CSharpSyntaxTree.ParseText(defineSource, parseOptions) },
            baseRefs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        using var ms = new MemoryStream();
        var emit = defining.Emit(ms);
        Assert.True(emit.Success, string.Join(Environment.NewLine, emit.Diagnostics.Where(d => d.Severity == DiagnosticSeverity.Error)));

        var refs = new List<MetadataReference>(baseRefs) { MetadataReference.CreateFromImage(ms.ToArray()) };
        var consuming = CSharpCompilation.Create(
            "ConsumingProject",
            new[] { CSharpSyntaxTree.ParseText(usageSource, parseOptions) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePackGenerator()).WithUpdatedParseOptions(parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(consuming, out _, out ImmutableArray<Diagnostic> diagnostics);

        var result = driver.GetRunResult();
        foreach (var gen in result.Results)
        {
            Assert.True(gen.Exception is null, "Generator threw: " + gen.Exception);
        }

        Assert.DoesNotContain(diagnostics, d => d.Id == "CS8785");
        Assert.DoesNotContain(result.Diagnostics, d => d.Id == "CS8785");
    }

    [Fact]
    public void A5_F1_ClosedGenericStructFromReferencedAssembly_DoesNotThrow()
    {
        string defineSource = """
using System;
using MessagePack;

namespace Lib
{
    [MessagePackObject]
    public struct GenericStruct<T>
    {
        [Key(0)]
        public T Value { get; set; }
    }
}
""";

        string usageSource = """
using System;
using MessagePack;
using Lib;

namespace TempProject
{
    [MessagePackObject]
    public class MyObject
    {
        [Key(0)]
        public GenericStruct<int> Value { get; set; }

        [Key(1)]
        public GenericStruct<string> Value2 { get; set; }
    }
}
""";
        RunScenario(defineSource, usageSource);
    }

    [Fact]
    public void A5_F1_ClosedGenericRecordStructFromReferencedAssembly_DoesNotThrow()
    {
        string defineSource = """
using System;
using MessagePack;

namespace Lib
{
    [MessagePackObject]
    public record struct GenericRecordStruct<T>
    {
        [Key(0)]
        public T Value { get; set; }
    }
}
""";

        string usageSource = """
using System;
using MessagePack;
using Lib;

namespace TempProject
{
    [MessagePackObject]
    public class MyObject
    {
        [Key(0)]
        public GenericRecordStruct<int> Value { get; set; }
    }
}
""";
        RunScenario(defineSource, usageSource);
    }
}
